import{_ as a,a0 as p,w as i,s as h,ao as l,I as r,x as e,a1 as o,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"10个 ssh 简单命令选项 | LCTT x X-CMD","titleTemplate":false,"description":"10个 ssh 简单命令选项 | LCTT (201404) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10个 ssh 简单命令选项 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10个 ssh 简单命令选项 | LCTT (201404) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201404/10 ssh options for a Secure shell for Safe Data Communication","title":"10个 ssh 简单命令选项","tag":"201404","desc":""},"relativePath":"201404/10 ssh options for a Secure shell for Safe Data Communication.md","filePath":"[post].md"}'),c={name:"201404/10 ssh options for a Secure shell for Safe Data Communication.md"};function d(g,s,S,m,u,f){const n=p("Link");return i(),h("div",null,[s[11]||(s[11]=l(`<h1 id="_10个-ssh-简单命令选项" tabindex="-1">10个 ssh 简单命令选项 <a class="header-anchor" href="#_10个-ssh-简单命令选项" aria-label="Permalink to “10个 ssh 简单命令选项”">​</a></h1><p>一个系统管理员可能会同时管理着多台服务器，这些服务器也许会放在不同的地方。要亲自一台一台的去访问来管理它们显然不是最好的方法，通过远程控制的方法应该是最有效的。远程访问最通用的一款应用程序就是 <strong>SSH</strong>（什么？你还用telnet？....$%@%&amp;W@$##）。</p><h3 id="ssh-是什么" tabindex="-1">SSH 是什么 <a class="header-anchor" href="#ssh-是什么" aria-label="Permalink to “SSH 是什么”">​</a></h3><p><strong>SSH（全称 Secure Shell)</strong>是一种加密的网络协议。使用该协议的数据将被加密，如果在传输中间数据泄漏，也可以确保没有人能读取出有用信息。要使用 SSH，目标机器应该安装 SSH 服务端应用程序，因为 <strong>SSH 是基于客户-服务模式的。</strong> 当你想安全的远程连接到主机，可中间的网络（比如因特网）并不安全，通常这种情况下就会使用 SSH。</p><h3 id="安装-ssh" tabindex="-1">安装 SSH <a class="header-anchor" href="#安装-ssh" aria-label="Permalink to “安装 SSH”">​</a></h3><p>的 Linux 系统默认已经安装了 SSH。如果碰巧你的机器没装（译注：我能吐槽么？没有不装ssh的Linux服务器吧，不过，大家要记得升级你的ssh服务器），我们可以手工来安装一下。最简单的方式就是使用 Linux 包管理器。</p><h3 id="基于-debian-ubuntu-的系统" tabindex="-1">基于 Debian / Ubuntu 的系统 : <a class="header-anchor" href="#基于-debian-ubuntu-的系统" aria-label="Permalink to “基于 Debian / Ubuntu 的系统 :”">​</a></h3><h4 id="安装-ssh-client" tabindex="-1">安装 ssh-client <a class="header-anchor" href="#安装-ssh-client" aria-label="Permalink to “安装 ssh-client”">​</a></h4><pre><code>$ sudo apt-get install openssh-client
</code></pre><h4 id="安装-ssh-server" tabindex="-1">安装 ssh-server <a class="header-anchor" href="#安装-ssh-server" aria-label="Permalink to “安装 ssh-server”">​</a></h4><pre><code>$ sudo apt-get install openssh-server
</code></pre><h3 id="基于-redhat-centos-的系统" tabindex="-1">基于 RedHat / CentOS 的系统 : <a class="header-anchor" href="#基于-redhat-centos-的系统" aria-label="Permalink to “基于 RedHat / CentOS 的系统 :”">​</a></h3><pre><code># yum install openssh-server openssh-clients
</code></pre><p>SSH 一旦安装上，我们就可以在终端下输入 <strong>ssh</strong> 来检查下安装的是否正常。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_client.png" alt="An ssh client"></p><h3 id="使用-ssh" tabindex="-1">使用 SSH <a class="header-anchor" href="#使用-ssh" aria-label="Permalink to “使用 SSH”">​</a></h3><p>提供了许多可使用的选项。这篇文章会介绍一些我们在日常操作中经常使用的选项。</p><h4 id="_1-无选项参数运行-ssh" tabindex="-1">1. 无选项参数运行 SSH <a class="header-anchor" href="#_1-无选项参数运行-ssh" aria-label="Permalink to “1. 无选项参数运行 SSH”">​</a></h4><p>通常使用 SSH 的方式就是不加任何选项参数,仅仅输入 &quot;<strong>ssh</strong>&quot;。下面是示例：</p><pre><code>$ ssh 192.168.0.103
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_ask_connect.png" alt="SSH connecti confirmation"></p><p>第一次连接目标主机时，ssh 会让你确认目标主机的真实性。如果你回答的是 <strong>NO</strong>，SSH 将不会继续连接，只有回答 <strong>Yes</strong> 才会继续（译注：会加入RSA key的指纹作为记录，如果下次连接发现指纹变化，会提示你）。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_connect.png" alt="Connecting to SSH"></p><p>下一次再登陆此主机时，SSH 就不会提示确认消息了。对此主机的真实验证信息已经默认保存在每个用户的 /home/user/.ssh 文件里。</p><h4 id="_2-指定登陆用户" tabindex="-1">2. 指定登陆用户 <a class="header-anchor" href="#_2-指定登陆用户" aria-label="Permalink to “2. 指定登陆用户”">​</a></h4><p>默认的，ssh 会尝试用当前用户作为用户名来连接。在上面的示例命令中，ssh 会尝试用用户名叫 pungki 的用户身份来登入服务器，这是因为用户 pungki 正在客户机上使用 ssh 客户端软件。</p><p>假如目标主机上没有叫 pungki 的用户呢？这时你就必须提供一个目标主机上存在的用户名。从一开始就要指定用户名的，可以使用 -l 选项参数。</p><pre><code>$ ssh -l leni 192.168.0.103
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_l.png" alt="Ssh using -l option"></p><p>我们也可以这样输入：</p><pre><code>$ ssh leni@192.168.0.0103
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_l_2.png" alt="Another way to supply username"></p><h4 id="_3-指定端口" tabindex="-1">3. 指定端口 <a class="header-anchor" href="#_3-指定端口" aria-label="Permalink to “3. 指定端口”">​</a></h4><p><strong>SSH 默认使用的端口号是 22。</strong>大多现代的 Linux 系统 22 端口都是开放的。如果你运行 ssh 程序而没有指定端口号，它直接就是通过 22 端口发送请求的。</p><p>一些系统管理员会改变 SSH 的默认端口号。让我们试试，现在端口号是 1234.要连上那主机，就要使用 *<strong>-p</strong> 选项，后面在加上 SSH 端口号。</p><pre><code>$ ssh 192.168.0.103 -p 1234
</code></pre><p>要改变端口号，我们需要修改 <strong>/etc/ssh/ssh_config</strong> 文件，找到此行：</p><pre><code>Port 22
</code></pre><p>把它换成其他的端口号，比如上面示例的 1234 端口，然后重启 SSH 服务。</p><h4 id="_4-对所有数据请求压缩" tabindex="-1">4.对所有数据请求压缩 <a class="header-anchor" href="#_4-对所有数据请求压缩" aria-label="Permalink to “4.对所有数据请求压缩”">​</a></h4><p>有了这个选项，所有通过 SSH 发送或接收的数据将会被压缩，并且任然是加密的。要使用 SSH 的压缩功能，使用 <strong>-C</strong> 选项。</p><pre><code>$ ssh -C 192.168.0.103
</code></pre><p>如果你的连网速度很慢的话，比如用 modem 上网，这个选项非常有用。但如果你使用的是像 LAN 或其它更高级网络的话，压缩反而会降低你的传输速度。可以使用 <strong>-o</strong> 选项加上<strong>压缩级别参数</strong>来控制压缩的级别，但这个选项仅仅只在 SSH-1 下起作用。</p><h4 id="_5-指定一个加密算法" tabindex="-1">5. 指定一个加密算法 <a class="header-anchor" href="#_5-指定一个加密算法" aria-label="Permalink to “5. 指定一个加密算法”">​</a></h4><p>SSH 提供了一些可用的加密算法。可以在 **/etc/ssh/ssh_config or ~/.ssh/config ** 文件中看到（如果存在的话）。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_cipher.png" alt="SSH cipher configuration example"></p><p>让我们试试比如你想使用 <strong>blowfish</strong> 算法来加密你的 SSH 会话，那么你只要把这一行加入你的 <strong>/etc/ssh/ssh_config or ~/.ssh/config</strong> 文件就可以：</p><pre><code>Cipher blowfish
</code></pre><p>默认的，SSH 会使用 3des 算法。</p><h4 id="_6-打开调试模式" tabindex="-1">6. 打开调试模式 <a class="header-anchor" href="#_6-打开调试模式" aria-label="Permalink to “6. 打开调试模式”">​</a></h4><p>因为某些原因，我们想要追踪调试我们建立的 SSH 连接情况。SSH 提供的 <strong>-v</strong> 选项参数正是为此而设的。</p><pre><code>$ ssh -v 192.168.0.103
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_v.png" alt="debug ssh connection"></p><h4 id="_7-绑定源地址" tabindex="-1">7. 绑定源地址 <a class="header-anchor" href="#_7-绑定源地址" aria-label="Permalink to “7. 绑定源地址”">​</a></h4><p>如果你的客户端有多于两个以上的 IP 地址，你就不可能分得清楚在使用哪一个 IP 连接到 SSH 服务器。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ifconfig.png" alt="More than 1 IP Address"></p><p>为了解决这种情况，我们可以使用 <strong>-b</strong> 选项来指定一个IP 地址。这个 IP 将会被使用做建立连接的源地址。</p><pre><code>$ ssh -b 192.168.0.200 -l leni 192.168.0.103
</code></pre><p>服务端，我们可以使用 netstat 命令来检查到服务的连接是否建立。可以看到 IP 为 192.168.0.200 的连接已经建立。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_bind.png" alt="Bind address using SSH"></p><h4 id="_8-使用其他配置文件" tabindex="-1">8. 使用其他配置文件 <a class="header-anchor" href="#_8-使用其他配置文件" aria-label="Permalink to “8. 使用其他配置文件”">​</a></h4><p>默认情况下，ssh 会使用位于 <strong>/etc/ssh/ssh_config</strong> 的配置文件。这个配置文件作用于系统的所有用户。但你想要为特定的用户指定特殊的设置的话，可以把配置放入 <strong>~/.ssh/config</strong> 文件中。如果此文件不存在，可以手工创建一个。</p><p>下面是一个通用 <strong>ssh_config</strong> 文件配置的例子。这配置文件位于 <strong>/home/pungki</strong> 目录下。</p><pre><code>Host 192.168.0.*
ForwardX11 yes
PasswordAuthentication yes
ConnectTimeout 10
Ciphers aes128-ctr,aes192-ctr,aes256-ctr,arcfour256,arcfour128,aes128-cbc,3des-cbc
Protocol 2
HashKnownHosts yes
</code></pre><p>要使用指定的配置文件，可以使用 <strong>-F</strong> 选项。</p><pre><code>$ ssh -F /home/pungki/my_ssh_config 192.168.0.101
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_F.png" alt="Specify your ssh_config"></p><h3 id="_9-使用-ssh-x11-forwarding" tabindex="-1">9. 使用 SSH X11 Forwarding <a class="header-anchor" href="#_9-使用-ssh-x11-forwarding" aria-label="Permalink to “9. 使用 SSH X11 Forwarding”">​</a></h3><p>某些时候，你可能想把服务端的 X11 应用程序显示到客户端计算机上，SSH 提供了 <strong>-X</strong> 选项。但要启用这功能，我们需要做些准备，下面是它的设置：</p><p>在服务器端，你需要使 <strong>/etc/ssh/ssh_config</strong> 文件中的行设置成 <strong>ForwardX11 yes 或者 X11Forwad yes</strong>，以启用 X11 Forwarding，重启 SSH 服务程序。</p><p>然后在客户端，输入 <strong>ssh -X user@host</strong>:</p><pre><code>$ ssh -X leni@192.168.0.101
</code></pre><p>一旦登陆，可以输入：</p><pre><code>$ echo $DISPLAY
</code></pre><p>来检查，你应该可以看到向如下所示的</p><pre><code>localhost:10:0
</code></pre><p>随后就可以运行应用了，仅仅只能输入应用程序的命令。让我们试试，比如想运行 xclock 程序，输入：</p><pre><code>$ xclock
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_Y.png" alt="Use X11 Formading"></p><p>它就运行起来了，xclock 确实是运行在远端系统的，但它在你的本地系统里显示了。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/02/xclock.png" alt="xclock"></p><h4 id="_10-可信任的-x11-转发" tabindex="-1">10. 可信任的 X11 转发 <a class="header-anchor" href="#_10-可信任的-x11-转发" aria-label="Permalink to “10. 可信任的 X11 转发”">​</a></h4><p>如果你敢肯定你的网络是安全的，那么你可以使用<strong>可信任的 X11 转发机制</strong>。这意味着远程的 X11 客户端可以完全的访问源 X11 显示内容。要使用此功能，可以使用 <strong>-Y</strong> 选项。</p><pre><code>$ ssh -Y leni@192.168.0.101
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/02/ssh_Y1.png" alt="SSH _Y for trusted connection"></p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>我们相信 SSH 的使用范围非常之广。SSH 给用户提供了网络连接的极大安全性和灵活性。通常我们都会输入 <strong>man ssh</strong> 和 <strong>man ssh_config</strong> 来显示它的用户手册及查看更多的细节。</p><p>（译注补充：建议使用ssh的协议版本2，因此请修改 ssh_config 文件的 Protocol 字段为：2，而将对协议1的支持取消。）</p><hr>`,89)),r("p",null,[s[1]||(s[1]=e("via: ",-1)),o(n,{href:"http://linoxide.com/linux-command/learn-ssh-connection-options/"},{default:t(()=>[...s[0]||(s[0]=[e("http://linoxide.com/linux-command/learn-ssh-connection-options/",-1)])]),_:1})]),r("p",null,[s[4]||(s[4]=e("译者：",-1)),o(n,{href:"https://github.com/runningwater"},{default:t(()=>[...s[2]||(s[2]=[e("runningwater",-1)])]),_:1}),s[5]||(s[5]=e(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[3]||(s[3]=[e("wxy",-1)])]),_:1})]),r("p",null,[s[8]||(s[8]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[6]||(s[6]=[e("LCTT",-1)])]),_:1}),s[9]||(s[9]=e(" 原创翻译，",-1)),o(n,{href:"http://linux.cn/"},{default:t(()=>[...s[7]||(s[7]=[e("Linux中国",-1)])]),_:1}),s[10]||(s[10]=e(" 荣誉推出",-1))])])}const H=a(c,[["render",d]]);export{b as __pageData,H as default};
